read_first_results.activity_query:
query($owner: String!, $name: String!, $items: Int!) {
  repository(owner: $owner, name: $name) {
    hasIssuesEnabled
    openPullRequests: pullRequests(states: OPEN) { totalCount }
    mergedPullRequests: pullRequests(states: MERGED) { totalCount }
    closedPullRequests: pullRequests(states: CLOSED) { totalCount }
    openIssues: issues(states: OPEN) { totalCount }
    closedIssues: issues(states: CLOSED) { totalCount }
    pinnedIssues(first: 3) { nodes { issue { number title url } } }
    pullRequests(last: $items, orderBy: {field: UPDATED_AT, direction: ASC}) {
      nodes { number title url state createdAt closedAt authorAssociation
      comments(last: 1) { nodes { authorAssociation body } } mergedAt mergedBy { login } }
    }
    issues(last: $items, orderBy: {field: UPDATED_AT, direction: ASC}) { nodes { number title url state createdAt closedAt authorAssociation
      comments(last: 1) { nodes { authorAssociation body } } } }
  }
}
